package candidate

import (
	"context"
	"encoding/json"
	"errors"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/ledger"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const opReassign = "bulk-reassign.v6"

func newReassign(pool *pgxpool.Pool) protocol.AssignHandler {
	return func(ctx context.Context, u app.Identity, key string, ids []string, assignee string) (protocol.AssignResult, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.AssignResult{}, false, &protocol.Rejection{Status: 404}
			}
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		defer tx.Rollback(ctx)
		if _, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role); err != nil {
			return protocol.AssignResult{}, false, err
		}
		lock, _ := json.Marshal([]string{opReassign, u.Tenant, u.User, key})
		if _, err = tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, string(lock)); err != nil {
			return protocol.AssignResult{}, false, err
		}
		hash := ledger.Fingerprint(opReassign+"\n"+assignee, ids)
		var savedHash string
		var saved []byte
		err = tx.QueryRow(ctx, `SELECT "requestHash",response FROM "ActionRequest"
		 WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, u.Tenant, u.User, opReassign, key).Scan(&savedHash, &saved)
		if err == nil {
			if savedHash != hash {
				return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
			}
			var body map[string]any
			if err = json.Unmarshal(saved, &body); err != nil {
				return protocol.AssignResult{}, false, err
			}
			rawIDs, ok := body["reassignedIds"]
			if !ok {
				return protocol.AssignResult{}, false, errors.New("invalid response: missing reassignedIds")
			}
			var reassignedIDs []string
			if err = json.Unmarshal(rawIDs.([]byte), &reassignedIDs); err != nil {
				return protocol.AssignResult{}, false, err
			}
			rawAssignee, ok := body["assignee"]
			if !ok {
				return protocol.AssignResult{}, false, errors.New("invalid response: missing assignee")
			}
			var assignedAssignee string
			if err = json.Unmarshal(rawAssignee.([]byte), &assignedAssignee); err != nil {
				return protocol.AssignResult{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.AssignResult{}, false, err
			}
			return protocol.AssignResult{Field: "reassignedIds", IDs: reassignedIDs, Assignee: assignedAssignee}, true, nil
		}
		if !errors.Is(err, pgx.ErrNoRows) {
			return protocol.AssignResult{}, false, err
		}
		// Check assignee is a valid approver in current tenant
		var assigneeValid bool
		err = tx.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM "TenantMember" WHERE "tenantId"=$1 AND "userId"=$2 AND role='approver' AND active=true)`, u.Tenant, assignee).Scan(&assigneeValid)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		if !assigneeValid {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 404}
		}
		// Check all targets are eligible: same tenant, created by someone else, status=submitted
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.AssignResult{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		if len(eligible) != len(ids) {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		// Update assigneeId for all eligible purchases
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET "assigneeId"=$4 WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User, assignee)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		// Insert assignment history records
		batch := &pgx.Batch{}
		for _, id := range ids {
			batch.Queue(`INSERT INTO "AssignmentHistory" ("tenantId","purchaseId","fromAssignee","toAssignee","changedBy",operation,"idempotencyKey")
			 VALUES ($1,$2,NULL,$3,$4,$5,$6)`, u.Tenant, id, assignee, u.User, opReassign, key)
		}
		result := protocol.AssignResult{Field: "reassignedIds", IDs: ids, Assignee: assignee}
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		batch.Queue(`INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
		 VALUES ($1,$2,$3,$4,$5,$6::jsonb)`, u.Tenant, u.User, opReassign, key, hash, string(response))
		if err = tx.SendBatch(ctx, batch).Close(); err != nil {
			return protocol.AssignResult{}, false, err
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.AssignResult{}, false, err
		}
		return result, false, nil
	}
}

